import json; import sys; from pathlib import Path; sys.path.insert(0, str(Path(__file__).parent.parent.parent)); from common.runtime import sla_manifest as gen; from tools import generate_sla_manifest as tool_shim; _committed_manifest = lambda: json.loads(gen.SLA_MANIFEST_PATH.read_text(encoding='utf-8'))
def test_AC_runtime_sla_manifest_1_committed_manifest_matches_live_dependency_manifest(): 'AC-runtime.sla-manifest.1'; rendered = gen.render_sla_manifest(gen.collect_sla_entries()); committed = gen.SLA_MANIFEST_PATH.read_text(encoding='utf-8'); assert committed == rendered, 'common/runtime/sla-manifest.generated.json is out of date with apps/backend/src/runtime/base/manifest.py. Run: python tools/generate_sla_manifest.py'
def test_AC_runtime_sla_manifest_2_production_entries_are_sla_bearing_and_complete():
    'AC-runtime.sla-manifest.2 EPIC-019'; committed = _committed_manifest(); production_entries = [e for e in committed['entries'] if e['tier'] == 'production']; names = [e['dependency'] for e in production_entries]; assert len(names) == len(set(names)), 'duplicate production SLA entry'; assert 'workflow_engine' in names, 'workflow_engine is required_in(production) — a prod-required dependency must carry SLA visibility even while its feature (EPIC-019 AC19.13) stays deferred'
    for entry in production_entries: assert set(entry) == {'tier', 'dependency', 'kind', 'summary'}; assert entry['kind'] in {'code_dominant', 'model_dominant'}; assert entry['summary'], f"{entry['dependency']} has no SLA summary"
def test_write_mode_emits_the_manifest_artifact(tmp_path, monkeypatch): target = tmp_path / 'sla-manifest.generated.json'; monkeypatch.setattr(gen, 'ROOT_DIR', tmp_path); monkeypatch.setattr(gen, 'SLA_MANIFEST_PATH', target); monkeypatch.setattr(sys, 'argv', ['generate_sla_manifest.py']); assert gen.main() == 0; written = target.read_text(encoding='utf-8'); assert written == gen.render_sla_manifest(gen.collect_sla_entries()); assert json.loads(written)['entries']
def test_check_mode_reds_on_stale_manifest(tmp_path, monkeypatch, capsys): stale = tmp_path / 'sla-manifest.generated.json'; stale.write_text('{"entries": []}\n', encoding='utf-8'); monkeypatch.setattr(gen, 'SLA_MANIFEST_PATH', stale); monkeypatch.setattr(sys, 'argv', ['generate_sla_manifest.py', '--check']); assert gen.main() == 1; assert 'sla-manifest.generated.json' in capsys.readouterr().out; assert tool_shim.main is gen.main
